// ---------- Analogy bridges ----------
window.BRIDGES = [
 {id:"syn", name:"Synonyms", sent:"A means the same as B", ex:"glad : happy"},
 {id:"ant", name:"Opposites", sent:"A is the opposite of B", ex:"timid : bold"},
 {id:"deg", name:"Degree", sent:"B is a much stronger form of A", ex:"big : enormous"},
 {id:"part", name:"Part → whole", sent:"A is a part of B", ex:"page : book"},
 {id:"whole", name:"Whole → part", sent:"A is made up of B parts", ex:"car : wheel"},
 {id:"group", name:"Member → group", sent:"A is one member of a B", ex:"wolf : pack"},
 {id:"type", name:"Kind of", sent:"A is a kind of B", ex:"oak : tree"},
 {id:"char", name:"Defining trait", sent:"A is always B (by definition)", ex:"desert : dry"},
 {id:"lack", name:"Without / free from", sent:"A is without B", ex:"penniless : money"},
 {id:"tool", name:"User → tool", sent:"A uses a B to work", ex:"painter : brush"},
 {id:"prod", name:"Maker → product", sent:"A makes B", ex:"baker : bread"},
 {id:"func", name:"Purpose", sent:"A is used to B (or to do B)", ex:"ladder : climb"},
 {id:"manner", name:"Way of doing", sent:"A is a particular way to B", ex:"whisper : speak"},
 {id:"cause", name:"Cause → effect", sent:"A causes / leads to B", ex:"heat : melting"},
 {id:"place", name:"Where it’s found", sent:"A works or is found in a B", ex:"teacher : classroom"}
];

// ---------- Original analogy questions ----------
// q: stem; ch: choices; a: index of answer; b: bridge id; br: bridge sentence for the stem; why: explanation
window.ANALOGIES = [
{id:"an1",b:"tool",q:"Surgeon is to scalpel as",ch:["climber is to summit","fencer is to épée","pilot is to passenger","author is to novel","teacher is to lesson"],a:1,br:"A surgeon uses a scalpel to do the job.",why:"A fencer uses an épée. Author : novel is maker → product. Climber : summit is a goal, not a tool."},
{id:"an2",b:"tool",q:"Carpenter is to hammer as",ch:["baker is to bread","drummer is to sticks","farmer is to field","tailor is to suit","dentist is to patient"],a:1,br:"A carpenter uses a hammer to work.",why:"A drummer uses sticks. Baker : bread and tailor : suit are maker → product; farmer : field is a place."},
{id:"an3",b:"tool",q:"Archer is to bow as",ch:["knight is to castle","sailor is to ocean","painter is to portrait","rower is to oar","singer is to audience"],a:3,br:"An archer uses a bow.",why:"A rower uses an oar. Painter : portrait is a product; knight : castle and sailor : ocean are places."},
{id:"an4",b:"tool",q:"Scribe is to quill as sculptor is to",ch:["statue","marble","chisel","museum","gallery"],a:2,br:"A scribe uses a quill to work.",why:"A sculptor uses a chisel. A statue is what she makes; marble is her material."},
{id:"an5",b:"prod",q:"Poet is to sonnet as",ch:["composer is to symphony","reader is to novel","actor is to stage","critic is to artist","farmer is to tractor"],a:0,br:"A poet writes (makes) a sonnet.",why:"A composer writes a symphony. Farmer : tractor is user → tool; actor : stage is a place."},
{id:"an6",b:"prod",q:"Potter is to vase as",ch:["cashier is to money","weaver is to rug","judge is to courtroom","miner is to pick","diver is to ocean"],a:1,br:"A potter makes a vase.",why:"A weaver makes a rug. Miner : pick is user → tool; judge : courtroom and diver : ocean are places."},
{id:"an7",b:"prod",q:"Playwright is to script as",ch:["director is to actor","usher is to ticket","choreographer is to dance","audience is to applause","stagehand is to curtain"],a:2,br:"A playwright creates a script.",why:"A choreographer creates a dance. An usher checks tickets but doesn’t make them."},
{id:"an8",b:"prod",q:"Mason is to wall as spider is to",ch:["fly","web","silk","leg","corner"],a:1,br:"A mason builds a wall.",why:"A spider builds a web. Silk is the material, not the finished product."},
{id:"an9",b:"part",q:"Stanza is to poem as",ch:["scene is to play","author is to book","stage is to actor","rhyme is to poet","novel is to chapter"],a:0,br:"A stanza is one section of a poem.",why:"A scene is one section of a play. Novel : chapter is the right idea in the WRONG order (whole → part)."},
{id:"an10",b:"part",q:"Rung is to ladder as",ch:["step is to staircase","hand is to climber","rope is to knot","peak is to valley","bridge is to river"],a:0,br:"A rung is one part of a ladder.",why:"A step is one part of a staircase. A knot is tied in a rope — it isn’t a part → whole pair."},
{id:"an11",b:"whole",q:"Book is to page as",ch:["chapter is to novel","staircase is to step","cement is to wall","architect is to plan","roof is to house"],a:1,br:"A book is made up of pages (whole → part).",why:"A staircase is made up of steps. Chapter : novel and roof : house go part → whole — backward."},
{id:"an12",b:"part",q:"Key is to piano as string is to",ch:["violin","music","conductor","melody","song"],a:0,br:"A key is a part of a piano.",why:"A string is a part of a violin. Melody and music are what the instrument produces."},
{id:"an13",b:"group",q:"Wolf is to pack as",ch:["bee is to swarm","lion is to cub","fish is to ocean","bird is to nest","horse is to stable"],a:0,br:"A wolf is a member of a pack.",why:"A bee is a member of a swarm. Nest, ocean and stable are places, not groups."},
{id:"an14",b:"group",q:"Fencer is to team as",ch:["actor is to cast","coach is to whistle","player is to score","singer is to song","climber is to rope"],a:0,br:"A fencer is one member of a team.",why:"An actor is one member of a cast. Coach : whistle and climber : rope are user → tool."},
{id:"an15",b:"group",q:"Star is to constellation as island is to",ch:["ocean","archipelago","continent","peninsula","beach"],a:1,br:"A star is one of the group that makes a constellation.",why:"An island is one of the group that makes an archipelago (a chain of islands). An island sits in the ocean — place, not group."},
{id:"an16",b:"group",q:"Musician is to orchestra as",ch:["soldier is to regiment","conductor is to baton","author is to library","sailor is to ship","painter is to canvas"],a:0,br:"A musician is a member of an orchestra.",why:"A soldier is a member of a regiment. A ship is where a sailor works, not a group of sailors."},
{id:"an17",b:"type",q:"Saga is to narrative as",ch:["sonnet is to poem","actor is to drama","chapter is to novel","sentence is to paragraph","ink is to page"],a:0,br:"A saga is a kind of narrative.",why:"A sonnet is a kind of poem. Chapter : novel and sentence : paragraph are part → whole."},
{id:"an18",b:"type",q:"Oak is to tree as",ch:["petal is to flower","salmon is to fish","root is to soil","seed is to fruit","leaf is to branch"],a:1,br:"An oak is a kind of tree.",why:"A salmon is a kind of fish. Petal : flower and leaf : branch are part → whole."},
{id:"an19",b:"type",q:"Waltz is to dance as sonata is to",ch:["piano","composition","composer","melody","concert"],a:1,br:"A waltz is a kind of dance.",why:"A sonata is a kind of musical composition. A melody is part of a sonata; a piano plays it."},
{id:"an20",b:"type",q:"Haiku is to poem as",ch:["broadsword is to weapon","novel is to chapter","poet is to rhyme","shield is to knight","word is to sentence"],a:0,br:"A haiku is a kind of poem.",why:"A broadsword is a kind of weapon. Word : sentence is part → whole."},
{id:"an21",b:"deg",q:"Annoy is to enrage as",ch:["tap is to pummel","shout is to whisper","sprint is to jog","like is to dislike","glance is to notice"],a:0,br:"To enrage is a much stronger form of to annoy.",why:"To pummel is a much stronger form of tapping. Sprint : jog goes from stronger to weaker — backward."},
{id:"an22",b:"deg",q:"Content (happy) is to elated as",ch:["tired is to exhausted","sad is to happy","cold is to cool","fast is to quick","loud is to noisy"],a:0,br:"Elated is an extreme form of content.",why:"Exhausted is an extreme form of tired. Cold : cool goes the wrong way; fast : quick are synonyms."},
{id:"an23",b:"deg",q:"Dislike is to abhor as",ch:["admire is to revere","hate is to love","walk is to stroll","praise is to censure","shout is to murmur"],a:0,br:"To abhor is to dislike intensely.",why:"To revere is to admire intensely. Walk : stroll is manner in reverse order (to stroll is a way to walk), not degree."},
{id:"an24",b:"deg",q:"Damp is to drenched as cool is to",ch:["warm","chilly","frigid","mild","brisk"],a:2,br:"Drenched is an extreme form of damp.",why:"Frigid is the extreme form of cool. Chilly is only a little colder — not extreme."},
{id:"an25",b:"deg",q:"Breeze is to gale as",ch:["drizzle is to downpour","sun is to cloud","snow is to ice","thunder is to lightning","fog is to mist"],a:0,br:"A gale is a much stronger breeze.",why:"A downpour is a much stronger drizzle. Fog : mist goes from thicker to thinner — backward."},
{id:"an26",b:"syn",q:"Acumen is to insight as",ch:["qualm is to misgiving","courage is to fear","hubbub is to silence","novice is to expert","edifice is to brick"],a:0,br:"Acumen means the same as insight.",why:"A qualm is a misgiving. Hubbub : silence and novice : expert are opposites."},
{id:"an27",b:"syn",q:"Corroborate is to confirm as",ch:["console is to comfort","encumber is to free","praise is to castigate","spurn is to accept","delay is to hurry"],a:0,br:"To corroborate is to confirm.",why:"To console is to comfort. The others are opposites."},
{id:"an28",b:"syn",q:"Dubious is to doubtful as callow is to",ch:["immature","wise","ancient","colorful","cautious"],a:0,br:"Dubious means doubtful.",why:"Callow means immature. Wise and ancient are close to the opposite."},
{id:"an29",b:"ant",q:"Taciturn is to talkative as",ch:["dauntless is to fearful","affluent is to wealthy","reclusive is to solitary","inept is to clumsy","elated is to happy"],a:0,br:"Taciturn is the opposite of talkative.",why:"Dauntless (fearless) is the opposite of fearful. The other pairs are synonyms."},
{id:"an30",b:"ant",q:"Exonerate is to convict as",ch:["praise is to condemn","console is to comfort","spurn is to reject","imperil is to endanger","verify is to confirm"],a:0,br:"Exonerate is the opposite of convict.",why:"Praise is the opposite of condemn. Every other pair is synonyms."},
{id:"an31",b:"ant",q:"Sublime is to ordinary as frugal is to",ch:["thrifty","wasteful","quiet","careful","wealthy"],a:1,br:"Sublime is the opposite of ordinary.",why:"Frugal is the opposite of wasteful. Thrifty is a synonym — the classic trap."},
{id:"an32",b:"ant",q:"Belligerent is to peaceful as",ch:["callow is to experienced","tentative is to uncertain","devious is to sly","quaint is to charming","skeptical is to doubtful"],a:0,br:"Belligerent is the opposite of peaceful.",why:"Callow (inexperienced) is the opposite of experienced. The rest are synonyms."},
{id:"an33",b:"lack",q:"Penniless is to money as",ch:["timid is to courage","wealthy is to gold","skilled is to talent","famous is to reputation","loud is to volume"],a:0,br:"Someone penniless is without money.",why:"Someone timid is without courage. Wealthy : gold, skilled : talent are HAVING, not lacking."},
{id:"an34",b:"lack",q:"Callow is to experience as",ch:["naive is to sophistication","wise is to knowledge","rich is to money","strong is to muscle","famous is to fans"],a:0,br:"Someone callow is without experience.",why:"Someone naive is without sophistication. The others all HAVE the second thing."},
{id:"an35",b:"lack",q:"Taciturn is to words as reclusive is to",ch:["company","silence","privacy","home","quiet"],a:0,br:"A taciturn person goes without many words.",why:"A reclusive person goes without company. A recluse HAS plenty of privacy and quiet — those are traps."},
{id:"an36",b:"lack",q:"Immune is to disease as",ch:["exempt is to tax","vulnerable is to attack","sick is to fever","guilty is to crime","careful is to detail"],a:0,br:"Someone immune is free from (protected from) disease.",why:"Someone exempt is free from a tax. Vulnerable is the opposite — open to attack."},
{id:"an37",b:"lack",q:"Anonymous is to name as",ch:["shapeless is to form","famous is to fame","colorful is to paint","written is to words","known is to identity"],a:0,br:"Something anonymous is without a name.",why:"Something shapeless is without form. Famous : fame is having, not lacking."},
{id:"an38",b:"char",q:"Braggart is to boastful as",ch:["glutton is to greedy","teacher is to strict","poet is to sad","climber is to tall","doctor is to wealthy"],a:0,br:"A braggart is boastful by definition.",why:"A glutton is greedy (for food) by definition. Some teachers are strict — but not by definition."},
{id:"an39",b:"char",q:"Recluse is to solitary as",ch:["miser is to stingy","pianist is to famous","coach is to loud","villain is to tall","sailor is to young"],a:0,br:"A recluse is solitary by definition.",why:"A miser is stingy by definition. The others describe some people, not all."},
{id:"an40",b:"char",q:"Desert is to arid as",ch:["glacier is to frozen","forest is to dangerous","city is to quiet","mountain is to green","river is to straight"],a:0,br:"A desert is always arid (dry).",why:"A glacier is always frozen. Mountains are not always green."},
{id:"an41",b:"char",q:"Optimist is to hopeful as skeptic is to",ch:["doubtful","cheerful","wealthy","foolish","talkative"],a:0,br:"An optimist is hopeful by definition.",why:"A skeptic is doubtful by definition. Cheerful fits an optimist, not a skeptic."},
{id:"an42",b:"func",q:"Antidote is to poison as",ch:["eraser is to mistake","pencil is to paper","snake is to venom","pill is to bottle","knife is to fork"],a:0,br:"An antidote is used to undo a poison.",why:"An eraser is used to undo a mistake. Snake : venom is source → product."},
{id:"an43",b:"func",q:"Ladder is to climb as",ch:["map is to navigate","book is to library","pen is to ink","shoe is to lace","boat is to lake"],a:0,br:"A ladder is used to climb.",why:"A map is used to navigate. Boat : lake is a place; shoe : lace is part."},
{id:"an44",b:"func",q:"Thermometer is to temperature as speedometer is to",ch:["speed","distance","fuel","engine","direction"],a:0,br:"A thermometer is used to measure temperature.",why:"A speedometer is used to measure speed. An engine is what makes the speed."},
{id:"an45",b:"func",q:"Testimonial is to praise as",ch:["apology is to regret","umbrella is to rain","trophy is to shelf","menu is to waiter","letter is to stamp"],a:0,br:"A testimonial is used to express praise.",why:"An apology is used to express regret. Umbrella : rain is protection from."},
{id:"an46",b:"manner",q:"Whisper is to speak as",ch:["trudge is to walk","listen is to hear","yell is to whisper","sing is to song","run is to race"],a:0,br:"To whisper is to speak in a quiet way.",why:"To trudge is to walk in a heavy, tired way. Sing : song is action → product."},
{id:"an47",b:"manner",q:"Gulp is to drink as",ch:["devour is to eat","cook is to dinner","sip is to gulp","sleep is to bed","chew is to teeth"],a:0,br:"To gulp is to drink quickly and greedily.",why:"To devour is to eat quickly and greedily. Chew : teeth is action → tool."},
{id:"an48",b:"manner",q:"Scribble is to write as mumble is to",ch:["speak","whisper","listen","write","sing"],a:0,br:"To scribble is to write in a messy way.",why:"To mumble is to speak in an unclear way. Whisper is another way of speaking, not what mumbling is a way of."},
{id:"an49",b:"manner",q:"Saunter is to walk as",ch:["peer is to look","shout is to voice","hear is to listen","read is to book","climb is to mountain"],a:0,br:"To saunter is to walk in a slow, relaxed way.",why:"To peer is to look in a close, searching way."},
{id:"an50",b:"cause",q:"Drought is to famine as",ch:["flood is to damage","cloud is to sky","farmer is to crop","harvest is to autumn","thirst is to water"],a:0,br:"A drought causes famine.",why:"A flood causes damage. Thirst : water is a need, not a cause."},
{id:"an51",b:"cause",q:"Virus is to illness as",ch:["spark is to fire","doctor is to nurse","sneeze is to cold","patient is to hospital","medicine is to pill"],a:0,br:"A virus causes illness.",why:"A spark causes fire. Sneeze : cold is backward — a cold causes the sneeze."},
{id:"an52",b:"cause",q:"Joke is to laughter as insult is to",ch:["offense","comedy","speech","friend","silence"],a:0,br:"A joke leads to laughter.",why:"An insult leads to offense."},
{id:"an53",b:"cause",q:"Practice is to skill as",ch:["exercise is to fitness","coach is to team","trophy is to shelf","school is to student","rain is to cloud"],a:0,br:"Practice leads to skill.",why:"Exercise leads to fitness. Rain : cloud is backward — clouds cause rain."},
{id:"an54",b:"place",q:"Fencer is to piste as",ch:["climber is to crag","actor is to script","swimmer is to goggles","judge is to verdict","pilot is to engine"],a:0,br:"A fencer competes on a piste (the fencing strip).",why:"A climber climbs on a crag. Swimmer : goggles is user → gear."},
{id:"an55",b:"place",q:"Bee is to hive as bear is to",ch:["den","honey","cub","claw","winter"],a:0,br:"A bee lives in a hive.",why:"A bear lives in a den. Honey is what bees make — a trap."},
{id:"an56",b:"place",q:"Judge is to courtroom as",ch:["chef is to kitchen","lawyer is to client","teacher is to lesson","doctor is to stethoscope","pilot is to passenger"],a:0,br:"A judge works in a courtroom.",why:"A chef works in a kitchen. Doctor : stethoscope is user → tool."}
];

